export function getBudgetMasterclassPointQuestions(language = "en", stepId = "") {
  const code = ["en", "tl", "es"].includes(String(language || "").toLowerCase())
    ? String(language).toLowerCase()
    : "en";
  const group = BUDGET_MASTERCLASS_POINT_QUESTIONS[String(stepId || "")] || {};
  return (group[code] || group.en || []).map((item) => ({ ...item }));
}
